# KzRDP session lifetime uses the published expiry, not a fresh full duration after setup.
$XyTag='KzRDP:session'
. "$PSScriptRoot/../lib/common.ps1"
. "$PSScriptRoot/../lib/ui.ps1"
$st=Read-Status
if (-not $st -or -not $st.expires_at) { throw 'Status sesi tidak memiliki expires_at' }
$stop=[DateTimeOffset]::Parse($st.expires_at).UtcDateTime.AddMinutes(-2)
$ip=$st.akses.tailscale.ip
$endpoint=if($st.akses.mode -eq 'portmap'){"$($st.akses.portmap.host):$($st.akses.portmap.port)"}else{"$ip`:3389"}
Write-Banner 'SUDAH ONLINE — sesi aktif' @(
  "Host      : $endpoint",
  "Username  : $($st.rdp_user)",
  'Password  : tidak ditulis di log (cek DM Telegram / dashboard)',
  "Berakhir  : $($st.expires_at) UTC"
) '1;32'
Write-Host (C '90' '  Jika desktop hitam tetapi pointer terlihat: Ctrl+Alt+End > Task Manager > Run new task > explorer.exe')
if ($env:GITHUB_STEP_SUMMARY) {
  @(
    '## 🟢 Sesi aktif', '',
    "Berakhir **$($st.expires_at) UTC**. Log di bawah menampilkan sisa waktu secara berkala.", '',
    '> Koneksi siap bukan bukti semua game berhasil dijalankan.', ''
  ) -join "`n" | Out-File -Append -Encoding utf8 $env:GITHUB_STEP_SUMMARY
}
# Statistik live (RAM/disk/CPU/uptime) dipublikasikan tiap 60 detik ke branch
# status supaya app XyDesk bisa menampilkannya tanpa web/token perantara —
# cukup baca out/rdp-status.json dari fork sendiri.
$nextPublish=(Get-Date).ToUniversalTime()
$sessionStart=[DateTimeOffset]::Parse($st.expires_at).UtcDateTime.AddMinutes(-[double]($env:DUR ?? 360))
$nextLog=(Get-Date).ToUniversalTime()
while ((Get-Date).ToUniversalTime() -lt $stop) {
  $left=$stop-(Get-Date).ToUniversalTime()
  if ((Get-Date).ToUniversalTime() -ge $nextLog) {
    Log "● online · sisa $($left.ToString('hh\:mm'))"
    $nextLog=(Get-Date).ToUniversalTime().AddMinutes(10)
  }
  if ((Get-Date).ToUniversalTime() -ge $nextPublish) {
    try {
      $os = Get-CimInstance Win32_OperatingSystem
      $ramTotal=[math]::Round($os.TotalVisibleMemorySize/1MB,2)
      $ramFree =[math]::Round($os.FreePhysicalMemory/1MB,2)
      $ramUsed =[math]::Round($ramTotal-$ramFree,2)
      $disk = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='C:'"
      $diskTotal=[math]::Round($disk.Size/1GB,1)
      $diskFree =[math]::Round($disk.FreeSpace/1GB,1)
      $cpuLoad = Get-CimInstance Win32_Processor | ForEach-Object { $_.LoadPercentage } | Where-Object { $_ }
      $cpu = if ($cpuLoad) { [int]($cpuLoad | Measure-Object -Average).Average } else { 0 }
      $uptime = [int]((Get-Date).ToUniversalTime() - $sessionStart).TotalMinutes
      if ($uptime -lt 0) { $uptime = 0 }
      Update-Status @{
        heartbeat_at=(Get-Date).ToUniversalTime().ToString('o')
        statistik=[pscustomobject]@{
          ram_total_gb=$ramTotal
          ram_used_gb=$ramUsed
          ram_free_gb=$ramFree
          disk_total_gb=$diskTotal
          disk_free_gb=$diskFree
          cpu_percent=$cpu
          uptime_menit=$uptime
          updated_at=(Get-Date).ToUniversalTime().ToString('o')
        }
      } | Out-Null
      & "$PSScriptRoot/publish-status.ps1" -Active $true
    } catch { Log "publikasi statistik gagal (lanjut): $($_.Exception.Message)" }
    $nextPublish=(Get-Date).ToUniversalTime().AddSeconds(60)
  }
  Start-Sleep -Seconds ([int][Math]::Max(1,[Math]::Min(60,$left.TotalSeconds)))
}
Log 'Durasi selesai; lanjut finalize.'

38f3b41579aa3354.data:
# Menghubungkan workflow ke layanan KzRDP: verifikasi token, kirim data RDP ke Telegram, tandai sesi selesai.
#   ready  : kirim host/port/username/password ke DM Telegram pemilik token (via server)
#   ended  : tandai sesi berakhir (memulai jeda 1 jam sebelum token baru)
param([Parameter(Mandatory)][ValidateSet('ready','ended')][string]$Action)
$ErrorActionPreference = 'Stop'
. "$PSScriptRoot/../lib/common.ps1"
$api = if ($env:KZRDP_API) { $env:KZRDP_API.TrimEnd('/') } else { 'https://rdp.kazamasite.biz.id' }

function Invoke-Kz([string]$Path, [hashtable]$Body) {
  $json = $Body | ConvertTo-Json -Compress -Depth 4
  for ($i = 1; $i -le 3; $i++) {
    try { return Invoke-RestMethod -Uri "$api$Path" -Method Post -ContentType 'application/json' -Body $json -TimeoutSec 30 }
    catch {
      $code = 0; try { $code = [int]$_.Exception.Response.StatusCode } catch {}
      $msg = ''; try { $msg = ($_.ErrorDetails.Message | ConvertFrom-Json).error } catch {}
      if ($code -ge 400 -and $code -lt 500) { throw "KzRDP menolak ($code): $msg" }
      if ($i -eq 3) { throw "KzRDP tidak terjangkau: $($_.Exception.Message)" }
      Start-Sleep -Seconds (3 * $i)
    }
  }
}

if (-not $env:KZRDP_SESSION_ID -or -not $env:KZRDP_SESSION_KEY) { Log 'Tidak ada sesi token; dilewati.'; exit 0 }
$auth = @{ session_id = $env:KZRDP_SESSION_ID; session_key = $env:KZRDP_SESSION_KEY }

if ($Action -eq 'ended') {
  try { Invoke-Kz '/api/v1/rdp/report' ($auth + @{ event = 'ended' }) | Out-Null; Log 'Sesi ditandai selesai.' }
  catch { Log "Gagal menandai selesai: $($_.Exception.Message)" }
  exit 0
}

# ready: tentukan host:port. Tunnel (dari server) > Portmap > IP Tailscale.
$st = Read-Status
$hostName = ''; $port = 3389
if ($env:KZRDP_TUNNEL_HOST -and $env:KZRDP_TUNNEL_PORT) {
  $hostName = $env:KZRDP_TUNNEL_HOST; $port = [int]$env:KZRDP_TUNNEL_PORT
} elseif ($st -and $st.akses -and $st.akses.portmap -and $st.akses.portmap.host -and [int]$st.akses.portmap.port -gt 0) {
  $hostName = "$($st.akses.portmap.host)"; $port = [int]$st.akses.portmap.port
} else {
  foreach ($ts in @('C:\Program Files\Tailscale\tailscale.exe', 'tailscale')) {
    try { $ip = (& $ts ip -4 2>$null | Select-Object -First 1); if ($ip -match '^\d{1,3}(\.\d{1,3}){3}$') { $hostName = $ip; break } } catch {}
  }
}
if (-not $hostName) { throw 'Host koneksi belum tersedia (Tailscale/portmap belum siap).' }
$user = if ($env:RDP_USER) { $env:RDP_USER } elseif ($st -and $st.rdp_user) { "$($st.rdp_user)" } else { 'kzadmin' }
$res = Invoke-Kz '/api/v1/rdp/report' ($auth + @{ event = 'ready'; host = $hostName; port = $port; username = $user; password = "$env:RDP_PASSWORD" })
Log "Data RDP dikirim ke Telegram (terkirim=$($res.delivered))."

b7375c21dc548e96.data:
# ============================================================================
#  publish-status.ps1 — publikasikan out/rdp-status.json ke branch `status`
#  1) GitHub Contents API via Invoke-RestMethod (Bearer GITHUB_TOKEN)  <- utama
#  2) Fallback: git push pakai header "Authorization: Bearer"          <- terbukti jalan
#  Verifikasi API mencocokkan run, attempt, dan active. Gagal publikasi = exit 1.
#  File TIDAK berisi password.
# ============================================================================
# [string] + koersi: supaya aman dipanggil baik sebagai `-Active $false` (blok pwsh)
# maupun lewat `pwsh -File ... -Active false` (argumen masuk sebagai string).
param([string]$Active = 'true')
$isActive = -not (@('false', '0', 'no', 'tidak', 'off', '') -contains ("$Active".Trim().ToLower()))
$ErrorActionPreference = 'Continue'
function Log([string]$m) { Write-Host "[KzRDP:status] $m" }

$repo = $env:GITHUB_REPOSITORY
# branch tujuan status (default 'status'); bisa diganti lewat env STATUS_BRANCH
# supaya run validasi/paralel tidak menimpa status sesi utama.
$statusBranch = if ($env:STATUS_BRANCH) { $env:STATUS_BRANCH.Trim() } else { 'status' }
# lokasi repo: Actions -> GITHUB_WORKSPACE, di luar Actions -> folder induk script
$ws   = if ($env:GITHUB_WORKSPACE) { $env:GITHUB_WORKSPACE } else { (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path }
$src  = Join-Path $ws 'out\rdp-status.json'
if (-not (Test-Path $src)) { Log "tidak ada $src — skip"; exit 0 }

$json = Get-Content $src -Raw | ConvertFrom-Json
if (-not $isActive) {
  $json | Add-Member -NotePropertyName stopped_at -NotePropertyValue (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') -Force
  $json.active = $false
  # sesi mati -> jangan tinggalkan endpoint koneksi di file publik (branch status)
  # helper: set/tambah properti walau belum ada (mis. status awal dari
  # setup-rdp.ps1 belum punya field id/host/port/address)
  function Clear-Field($obj, [string]$name, $value) {
    if ($null -eq $obj) { return }
    $obj | Add-Member -NotePropertyName $name -NotePropertyValue $value -Force
  }
  if ($json.PSObject.Properties['akses']) {
    if ($json.akses.PSObject.Properties['tunnel']) {
      Clear-Field $json.akses.tunnel 'host'    ''
      Clear-Field $json.akses.tunnel 'port'    0
      Clear-Field $json.akses.tunnel 'address' ''
    }
    if ($json.akses.PSObject.Properties['portmap']) { Clear-Field $json.akses.portmap 'host' ''; Clear-Field $json.akses.portmap 'port' 0 }
    if ($json.akses.PSObject.Properties['tailscale']) {
      Clear-Field $json.akses.tailscale 'ip' ''
      Clear-Field $json.akses.tailscale 'magicdns' ''
      Clear-Field $json.akses.tailscale 'hostname' ''
      Clear-Field $json.akses.tailscale 'funnel_addr' ''
    }
  }
  # sisa field lama (versi Tailscale/XyDesk) kalau masih ada di file
  if ($json.PSObject.Properties['tailscale_ip'])  { $json.tailscale_ip  = '' }
  if ($json.PSObject.Properties['tailscale_dns']) { $json.tailscale_dns = '' }
  if ($json.PSObject.Properties['extras']) {
    if ($json.extras.PSObject.Properties['xydesk_id'])  { $json.extras.xydesk_id  = '' }
    if ($json.extras.PSObject.Properties['xydesk_ids']) { $json.extras.xydesk_ids = @() }
  }
  Log 'status inactive: alamat tunnel + Tailscale dibersihkan dari file publik'
}
$json | ConvertTo-Json -Depth 6 | Set-Content -Path $src -Encoding utf8

function GH([string]$method, [string]$apiPath, $body) {
  $hdrs = @{ Authorization = "Bearer $env:GITHUB_TOKEN"; Accept = 'application/vnd.github+json'; 'User-Agent' = 'KzRDP' }
  try {
    $p = @{ Uri = "https://api.github.com$apiPath"; Method = $method; Headers = $hdrs; TimeoutSec = 30 }
    if ($null -ne $body) { $p.Body = ($body | ConvertTo-Json -Depth 6); $p.ContentType = 'application/json' }
    Invoke-RestMethod @p
  } catch { Log "GH $method $apiPath -> $($_.Exception.Message)"; $null }
}

# ---- cara 1: Contents API ----
try {
  $ref = GH 'GET' "/repos/$repo/git/ref/heads/$statusBranch" $null
  if (-not $ref) {
    $db   = (GH 'GET' "/repos/$repo" $null).default_branch
    if (-not $db) { throw 'default branch tidak diketahui (token tidak valid / tanpa scope repo?)' }
    $sha0 = (GH 'GET' "/repos/$repo/git/ref/heads/$db" $null).object.sha
    if (-not $sha0) { throw "default branch sha tidak diketahui" }
    GH 'POST' "/repos/$repo/git/refs" @{ ref = "refs/heads/$statusBranch"; sha = $sha0 } | Out-Null
    Log "branch '$statusBranch' dibuat (via API)"
  }
  $b64  = [Convert]::ToBase64String([IO.File]::ReadAllBytes($src))
  foreach ($remotePath in @('rdp-status.json', 'out/rdp-status.json')) {
    $body = @{ message = "KzRDP status update (run $($env:GITHUB_RUN_NUMBER))"; content = $b64; branch = $statusBranch }
    $cur  = GH 'GET' "/repos/$repo/contents/$remotePath`?ref=$statusBranch" $null
    if ($cur -and $cur.sha) { $body.sha = $cur.sha }
    $res = GH 'PUT' "/repos/$repo/contents/$remotePath" $body
    if ($res -and $res.content) { Log "Contents API OK ($remotePath -> commit $($res.commit.sha.Substring(0,7)))" }
    elseif ($remotePath -eq 'rdp-status.json') { throw "PUT contents tidak mengembalikan hasil" }
  }
} catch { Log "cara-1 gagal ($($_.Exception.Message)) — lanjut fallback git" }

# ---- cara 2 (fallback): git push + Bearer header ----
function Verify-Published {
  for ($i = 0; $i -lt 6; $i++) {
    Start-Sleep -Seconds 5
    try {
      $r = Invoke-RestMethod "https://raw.githubusercontent.com/$repo/$statusBranch/rdp-status.json?r=$i$((Get-Date).Minute)" -TimeoutSec 10
      if ($r -and "$($r.run_id)" -eq "$($env:GITHUB_RUN_ID)") { return $true }
    } catch {}
  }
  return $false
}

function Verify-PublishedAPI {
  try {
    $c = GH 'GET' "/repos/$repo/contents/rdp-status.json?ref=$statusBranch" $null
    if ($c -and $c.content) {
      $t = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($c.content)) | ConvertFrom-Json
      return ("$($t.run_id)" -eq "$($env:GITHUB_RUN_ID)" -and "$($t.run_attempt)" -eq "$($json.run_attempt)" -and [bool]$t.active -eq $isActive)
    }
  } catch {}
  return $false
}

if (-not (Verify-PublishedAPI)) {
  Log "verifikasi belum lolos — coba fallback git push..."
  $tmp = Join-Path $env:RUNNER_TEMP ("kzrdpstatus-" + (Get-Random -Maximum 999999))
  try {
    git init -q -b $statusBranch $tmp | Out-Null
    Copy-Item $src (Join-Path $tmp 'rdp-status.json') -Force
    New-Item -ItemType Directory -Path (Join-Path $tmp 'out') -Force | Out-Null
    Copy-Item $src (Join-Path $tmp 'out\rdp-status.json') -Force
    Push-Location $tmp
    git config user.name  "github-actions[bot]" | Out-Null
    git config user.email "41898282+github-actions[bot]@users.noreply.github.com" | Out-Null
    git add rdp-status.json out/rdp-status.json
    git -c commit.gpgsign=false commit -q -m "KzRDP status update" | Out-Null
    $out = git -c "http.extraHeader=Authorization: Bearer $env:GITHUB_TOKEN" push --force "https://github.com/$repo.git" "HEAD:refs/heads/$statusBranch" 2>&1
    $out | ForEach-Object { Log "git: $_" }
    Pop-Location
  } catch {
    if ((Get-Location).Path -eq $tmp) { Pop-Location }
    Log "git push error: $($_.Exception.Message)"
  }
}

if (Verify-PublishedAPI) {
  Log "OK — status run/attempt/active terverifikasi melalui GitHub API."
  exit 0
}
Log 'Gagal mempublikasikan status. Dashboard tidak dapat menyediakan koneksi; periksa izin Contents write workflow.'
exit 1

